#!/usr/bin/env bash
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing deterministic-grader fix..."
decode "fix_grader_det.py" << 'B64EOF'

B64EOF
python fix_grader_det.py && rm fix_grader_det.py
echo "Done. Verify determinism, then re-run the table."